// Baca CONFIG (key/value) -> retensi housekeeping MSG_BUFFER.
//
// INVARIANT WAJIB (lihat sticky note di workflow ini): msg_buffer_retention_hours
// (jam, dipakai DI SINI) HARUS lebih besar dari msg_buffer_ttl_minutes (menit,
// dipakai workflow UTAMA untuk menggabungkan pesan beruntun / merge debounce).
// Kalau tidak, baris yang masih dibutuhkan untuk merge bisa keburu terhapus.
const rows = $input.all().map(i => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key || '').trim();
  if (k) cfg[k] = (r.value !== undefined && r.value !== null) ? r.value : '';
}
const num = (k, d) => {
  const raw = cfg[k];
  if (raw === undefined || raw === '') return d;
  const n = Number(raw);
  return isNaN(n) ? d : n;
};

const retentionHours = num('msg_buffer_retention_hours', 2);
const ttlMinutes = num('msg_buffer_ttl_minutes', 30); // hanya dibaca untuk validasi invariant

if (retentionHours * 60 <= ttlMinutes) {
  console.warn(`⚠️ INVARIANT DILANGGAR: msg_buffer_retention_hours (${retentionHours} jam = ${retentionHours * 60} menit) harus LEBIH BESAR dari msg_buffer_ttl_minutes (${ttlMinutes} menit). Baris yang masih dipakai workflow utama untuk merge debounce berisiko terhapus duluan. Perbaiki nilai di tab CONFIG. Penghapusan tetap jalan dengan nilai retensi yang di-set admin.`);
}

return [{ json: {
  retention_hours: retentionHours,
  retention_ms: retentionHours * 60 * 60 * 1000,
  ttl_minutes: ttlMinutes
} }];

// ====================================================================
// PICK EXPIRED BLOCK — MSG_BUFFER housekeeping
// MSG_BUFFER bersifat append-only => ts naik seiring nomor baris =>
// baris kedaluwarsa (paling lama) SELALU blok kontigu di bagian atas
// (mulai baris 2). Jadi cukup 1x delete range (hemat kuota API), bukan
// hapus per baris satu-satu.
//
// Retensi dibaca dari CONFIG via node "Parse Config" (msg_buffer_retention_hours,
// default 2 jam) — HARUS > msg_buffer_ttl_minutes di workflow utama (lihat
// sticky note + warning di "Parse Config").
// ====================================================================
const RETENTION_MS = $('Parse Config').first().json.retention_ms;
const cutoff = Date.now() - RETENTION_MS;

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.row_number !== undefined && Number(r.row_number) >= 2)
  .sort((a, b) => Number(a.row_number) - Number(b.row_number)); // menaik (atas -> bawah)

if (!rows.length) {
  console.log('🧹 MSG_BUFFER kosong / hanya header — tidak ada yang dihapus.');
  return [];
}

// Hitung run kontigu baris kedaluwarsa mulai dari baris teratas. Berhenti di
// baris pertama yang MASIH segar atau yang ts-nya tidak valid — defensif:
// jangan pernah hapus baris yang tidak bisa dipastikan kedaluwarsanya.
let count = 0;
for (const r of rows) {
  const ts = Number(r.ts);
  const valid = Number.isFinite(ts) && ts > 0;
  if (valid && ts < cutoff) {
    count++;
  } else {
    if (!valid) {
      console.warn(`⚠️ Baris ${r.row_number} ts tidak valid ("${r.ts}") — stop, tidak hapus lebih jauh.`);
    }
    break;
  }
}

if (count === 0) {
  console.log('🧹 Tidak ada baris kedaluwarsa — buffer sudah ramping.');
  return [];
}

const startRow = Number(rows[0].row_number); // normalnya 2
console.log(`🧹 Hapus ${count} baris kedaluwarsa: baris ${startRow}..${startRow + count - 1}.`);
return [{ json: { startRow, count } }];
